-- Preserve the two existing case-study URLs when switching from static cards to CMS-backed records.
WITH entries(slug,title,content) AS (VALUES
('portfolio/ssl-scanner','A clearer view of website security.','{"category":"Engineering Tools","description":"A custom website SSL-error scanning script, documented by an original client review.","body":"The client review describes commissioning Anil to code a script for daily SSL-error checks across a large set of websites. It confirms that the requested script was delivered. The review documents the requested scope; it is not an independently measured claim of production scan volume.\n\nThe implementation language, deployment architecture and confidential delivery files are not established by the public review and are not invented here.","role":"Software developer · as described in the client review","project_status":"Historical completed delivery","technologies":[],"features":["Custom website SSL-error scanning script","Daily scanning requirement described by the client"],"sources":[{"label":"Original client feedback","url":"https://anibish.com/reviews"}],"featured":false,"evidence_attested":true,"mode":"enhance"}'::jsonb),
('portfolio/responsive-websites','Websites, built around real businesses.','{"category":"Freelance Client Projects","description":"Responsive website delivery documented in authentic client feedback.","body":"The original review describes a fast, responsive website and confirms that Anil followed the client’s instructions. This concise service-delivery record preserves that verified account without inventing a framework, business outcome, customer name or commercial metric.\n\nPrivate requirements, account details and delivery files remain confidential. The associated review is shown below in its original wording and rating where available.","role":"Website developer · as described in the client review","project_status":"Historical completed delivery","technologies":[],"features":["Responsive website delivery","Implementation based on the client brief"],"sources":[{"label":"Original client feedback","url":"https://anibish.com/reviews"}],"featured":false,"evidence_attested":true,"mode":"enhance"}'::jsonb)
)
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at)
SELECT slug,title,'portfolio','published',content,content,jsonb_build_object('title',title,'description',content->>'description'),jsonb_build_object('title',title,'description',content->>'description'),now() FROM entries ON CONFLICT(slug) DO NOTHING;
INSERT INTO audit_log(action,resource,detail) VALUES('portfolio.legacy_routes_preserved','historical-case-studies','{"source":"existing public review-backed case studies","private_files_published":false}');
